"""Actions-only publication contracts using generated bytes and a stateful GitHub port."""
import copy
import hashlib
import json
from pathlib import Path
import tempfile
import unittest
import urllib.parse

from miniapp_authoring_sdk_test import TOOLS, load, packager, sdk

release = load('miniapp_release', TOOLS / 'miniapp_release.py')


class GitHub:
    def __init__(self, error_type=release.PublicationError):
        self.error_type = error_type
        self.release = None
        self.calls = []
        self.uploaded = []
        self.tag_sha = 'a' * 40
        self.bad_digest = False
        self.lose_upload_response = False
        self.move_after_upload = False

    def __call__(self, url, method='GET', body=None, missing_ok=False):
        self.calls.append((url, method, body))
        path = urllib.parse.urlparse(url).path
        if method == 'GET' and '/git/ref/tags/' in path:
            return {'object': {'type': 'commit', 'sha': self.tag_sha}}
        if method == 'GET' and '/releases/tags/' in path:
            return copy.deepcopy(self.release)
        if method == 'POST' and path.endswith('/releases'):
            if self.release is not None:
                raise AssertionError('duplicate release creation')
            self.release = {**body, 'id': 42, 'assets': [],
                            'html_url': 'https://github.com/ci/example/releases/tag/untagged-draft'}
            return copy.deepcopy(self.release)
        if method == 'POST' and path.endswith('/assets'):
            name = urllib.parse.parse_qs(urllib.parse.urlparse(url).query)['name'][0]
            if name in self.uploaded:
                raise AssertionError('asset overwritten or uncertain write retried')
            self.uploaded.append(name)
            asset = {'name': name, 'size': len(body), 'state': 'uploaded',
                     'digest': 'sha256:' + ('0' * 64 if self.bad_digest else hashlib.sha256(body).hexdigest())}
            self.release['assets'].append(asset)
            if self.move_after_upload:
                self.tag_sha = 'b' * 40
            if self.lose_upload_response:
                self.lose_upload_response = False
                raise self.error_type('PUBLICATION_UNCERTAIN_RECONCILE_BEFORE_RETRY')
            return copy.deepcopy(asset)
        if method == 'PATCH' and path.endswith('/releases/42'):
            self.release['draft'] = body['draft']
            self.release['html_url'] = 'https://github.com/ci/example/releases/tag/v1.0.0'
            return copy.deepcopy(self.release)
        raise AssertionError('unexpected request: ' + method + ' ' + url)

    def writes(self):
        return [call for call in self.calls if call[1] != 'GET']


class Publication(unittest.TestCase):
    def setUp(self):
        self.temporary = tempfile.TemporaryDirectory()
        self.workspace = Path(self.temporary.name)
        sdk.execute({'action': 'create', 'project': 'counter', 'appId': 'org.test.counter',
                     'publisherId': 'test', 'displayName': 'Counter', 'version': '1.0.0'}, self.workspace)
        self.export = sdk.execute({'action': 'export', 'project': 'counter'}, self.workspace)
        self.root = self.workspace / 'repository'
        for file in self.export['githubFiles']:
            target = self.root / file['path']
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_text(file['content'])
        self.context = {'GITHUB_EVENT_NAME': 'workflow_dispatch', 'GITHUB_REPOSITORY': 'ci/example',
                        'MINIAPP_PUBLISH': 'true', 'GITHUB_REF_TYPE': 'tag', 'GITHUB_REF_NAME': 'v1.0.0',
                        'GITHUB_SHA': 'a' * 40, 'EXPECTED_SOURCE_SHA': 'a' * 40}
        packager.prepare(self.root, self.root / 'dist', 'a' * 40)
        self.publisher = load('exported_release', self.root / 'tools/publish.py')
        self.api = GitHub(self.publisher.PublicationError)

    def tearDown(self):
        self.temporary.cleanup()

    def publish(self, context=None):
        return self.publisher.publish(self.root, self.root / 'dist', context or self.context, self.api)

    def test_actual_export_publication_and_read_only_reconciliation(self):
        result = self.publish()
        self.assertEqual(result['state'], 'github_published')
        self.assertEqual(result['sourceSha'], 'a' * 40)
        self.assertEqual(result['releaseUrl'], 'https://github.com/ci/example/releases/tag/v1.0.0')
        self.assertFalse(result['signed'])
        self.assertFalse(result['installable'])
        self.assertEqual(result['registryState'], 'not_submitted')
        self.assertEqual(len(self.api.writes()), 5)  # draft, three assets, publication
        self.assertEqual(len(self.api.uploaded), 3)
        previous = len(self.api.writes())
        self.assertEqual(self.publish(), result)
        self.assertEqual(len(self.api.writes()), previous)
        workflow = next(f['content'] for f in self.export['githubFiles'] if f['path'].endswith('miniapp.yml'))
        self.assertIn('needs: package', workflow)
        self.assertIn("github.event_name == 'workflow_dispatch' && inputs.publish", workflow)
        self.assertEqual(self.export['publication']['state'], 'source_exported')
        self.assertFalse(self.export['publication']['githubPublished'])

    def test_authorization_version_and_source_fail_before_mutations(self):
        for changes in [{'GITHUB_EVENT_NAME': 'push'}, {'GITHUB_EVENT_NAME': 'pull_request'},
                        {'MINIAPP_PUBLISH': 'false'}, {'GITHUB_REF_TYPE': 'branch'},
                        {'EXPECTED_SOURCE_SHA': 'b' * 40}, {'GITHUB_REF_NAME': 'v9.0.0'},
                        {'GITHUB_REPOSITORY': '../../other/repo'}]:
            with self.subTest(changes=changes), self.assertRaises(self.publisher.PublicationError):
                self.publish({**self.context, **changes})
        self.assertEqual(self.api.writes(), [])

    def test_changed_source_after_packaging_never_publishes(self):
        (self.root / 'src/app.js').write_text('changed after tests')
        with self.assertRaisesRegex(self.publisher.PublicationError, 'SOURCE_BYTES_MISMATCH'):
            self.publish()
        self.assertEqual(self.api.calls, [])

    def test_lost_upload_response_is_not_retried_and_next_call_reconciles(self):
        self.api.lose_upload_response = True
        with self.assertRaisesRegex(self.publisher.PublicationError, 'UNCERTAIN'):
            self.publish()
        self.assertEqual(len(self.api.uploaded), 1)
        self.assertTrue(self.api.release['draft'])
        self.assertEqual(self.publish()['state'], 'github_published')
        self.assertEqual(len(self.api.uploaded), 3)
        self.assertEqual(len(self.api.writes()), 5)

    def test_asset_hash_mismatch_or_tag_move_leaves_draft_and_never_overwrites(self):
        self.api.bad_digest = True
        with self.assertRaisesRegex(self.publisher.PublicationError, 'ASSET_MISMATCH'):
            self.publish()
        self.assertTrue(self.api.release['draft'])
        writes = len(self.api.writes())
        with self.assertRaisesRegex(self.publisher.PublicationError, 'ASSET_MISMATCH'):
            self.publish()
        self.assertEqual(len(self.api.writes()), writes)
        self.api = GitHub(self.publisher.PublicationError)
        self.api.move_after_upload = True
        with self.assertRaisesRegex(self.publisher.PublicationError, 'TAG_MOVED'):
            self.publish()
        self.assertTrue(self.api.release['draft'])
        self.assertEqual(len(self.api.uploaded), 1)

    def test_existing_unowned_release_is_not_adopted(self):
        self.api.release = {'id': 42, 'tag_name': 'v1.0.0', 'draft': True, 'body': 'other release'}
        with self.assertRaisesRegex(self.publisher.PublicationError, 'RELEASE_CONFLICT'):
            self.publish()
        self.assertEqual(self.api.writes(), [])

    def test_credential_transport_cannot_be_redirected_to_another_host_or_repository(self):
        api = self.publisher.github_api('fixture-not-a-secret', 'ci/example')
        for url in ['https://evil.example/repos/ci/example/releases',
                    'https://api.github.com/repos/ci/other/releases',
                    'http://api.github.com/repos/ci/example/releases']:
            with self.assertRaisesRegex(self.publisher.PublicationError, 'ENDPOINT_DENIED'):
                api(url)
        self.assertIsNone(release.NoRedirect().redirect_request(None, None, 302, '', {}, 'https://evil.example'))


if __name__ == '__main__':
    unittest.main()
